import "../../styles/index-base.css";
import "../../styles/components/search-input.css";
import { MagnifyingGlass, X } from "@phosphor-icons/react";
import { forwardRef, useId, useState, type InputHTMLAttributes } from "react";
import { cn } from "../../lib/cn";

export type SearchInputProps = Omit<InputHTMLAttributes<HTMLInputElement>, "type"> & {
  label?: string;
  loading?: boolean;
  onClear?: () => void;
  shortcut?: string;
};

export const SearchInput = forwardRef<HTMLInputElement, SearchInputProps>(function SearchInput({ id: providedId, label = "Search", loading, onClear, shortcut, className, value, defaultValue, onChange, ...props }, ref) {
  const generatedId = useId();
  const id = providedId ?? generatedId;
  const controlled = value !== undefined;
  const [uncontrolledValue, setUncontrolledValue] = useState(() => String(defaultValue ?? ""));
  const currentValue = controlled ? String(value ?? "") : uncontrolledValue;
  const hasValue = currentValue.length > 0;
  return (
    <div className="ix-search-field">
      <label className="ix-sr-only" htmlFor={id}>{label}</label>
      <div className={cn("ix-search", className)} data-loading={loading || undefined}>
        {loading ? <span className="ix-spinner ix-search__spinner" aria-hidden="true" /> : <MagnifyingGlass className="ix-search__icon" aria-hidden="true" />}
        <input
          ref={ref}
          id={id}
          type="search"
          value={controlled ? value : uncontrolledValue}
          aria-busy={loading || undefined}
          onChange={(event) => {
            if (!controlled) setUncontrolledValue(event.currentTarget.value);
            onChange?.(event);
          }}
          {...props}
        />
        {hasValue && onClear ? <button type="button" aria-label="Clear search" onClick={() => { if (!controlled) setUncontrolledValue(""); onClear(); }}><X /></button> : shortcut ? <kbd>{shortcut}</kbd> : null}
      </div>
    </div>
  );
});

/* Generated from src/styles.css. Do not edit directly. */

@layer index.tokens, index.base, index.components;

@layer index.components {
.ix-search { display: flex; width: 100%; min-width: 220px; height: 32px; align-items: center; gap: 7px; padding: 0 8px; border: 1px solid var(--ix-border); border-radius: var(--ix-radius-sm); background: var(--ix-control-surface); box-shadow: var(--ix-shadow-control); transition: border-color var(--ix-hover-duration) ease, box-shadow var(--ix-hover-duration) ease; }

.ix-search:focus-within { border-color: var(--ix-focus-control); box-shadow: var(--ix-shadow-control); }

.ix-search__icon { width: 14px; height: 14px; color: var(--ix-ink-tertiary); }

.ix-search__spinner { width: 13px; height: 13px; }

.ix-search input { min-width: 0; height: 100%; flex: 1; border: 0; outline: 0; background: transparent; color: var(--ix-ink); font: inherit; font-size: var(--ix-type-ui); -webkit-appearance: none; appearance: none; }

.ix-search input::-webkit-search-cancel-button { display: none; }

.ix-search input::placeholder { color: var(--ix-ink-tertiary); }

.ix-search button { display: grid; width: 22px; height: 22px; place-items: center; border: 0; border-radius: 5px; background: transparent; color: var(--ix-ink-tertiary); cursor: pointer; }

.ix-search button svg { width: 12px; height: 12px; }

.ix-search kbd { display: inline-flex; flex: 0 0 auto; align-items: center; justify-content: center; color: var(--ix-ink-tertiary); font-size: 10px; line-height: 1; white-space: nowrap; }

@media (hover: hover) and (pointer: fine) {
.ix-search button:hover { background: var(--ix-hover); color: var(--ix-ink); }

.ix-search:hover { border-color: var(--ix-border-strong); }
}

.ix-search input:focus-visible { outline: 0; }

.ix-sr-only,
.ix-sr-only:not(:focus):not(:active) {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
}

.ix-spinner { width: 13px; height: 13px; border: 1.5px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: ix-spin 0.75s linear infinite; }

.ix-search button { transition: color var(--ix-hover-duration), background-color var(--ix-hover-duration), transform var(--ix-press-duration) var(--ix-ease-out); }

.ix-search button:active { transform: scale(.96); }

@media (prefers-reduced-motion: reduce) {
.ix-search button:active { transform: none; }

.ix-spinner { animation-duration: 2.4s; }
}

@keyframes ix-spin { to { transform: rotate(360deg); } }
}
